pragma solidity ^0.8.18;

import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {Pausable} from "@openzeppelin/contracts/security/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/security/ReentrancyGuard.sol";

import {IBondedArbitrator} from "./interfaces/IBondedArbitrator.sol";
import {IEscrow} from "./interfaces/IEscrow.sol";
import {INonPaymentVerifier} from "./interfaces/INonPaymentVerifier.sol";
import {INullifierRegistryV2} from "./interfaces/INullifierRegistryV2.sol";
import {IOrchestratorV4} from "./interfaces/IOrchestratorV4.sol";
import {IStakeVaultV2} from "./interfaces/IStakeVaultV2.sol";

/**
 * @title BondedArbitrator
 * @notice OrchestratorV4 arbitrator that releases an intent only against locked stake. An operator releases funds
 * to the intent recipient and locks the same amount of its bond owner's StakeVaultV2 stake for the payment method's
 * dispute window. The depositor takes the share of that stake a signed scan of the seller account shows was never
 * paid: all of it when nothing matching arrived, the shortfall when less arrived. Otherwise the stake unlocks at
 * maturity, or earlier when the depositor confirms the payment.
 * @dev The signal policy names this contract as the intent arbitrator. It exposes only release, so the arbitrator's
 * cancel and extend powers stay unused. Authorize it as a StakeVaultV2 controller and a NullifierRegistryV2 writer.
 */
contract BondedArbitrator is IBondedArbitrator, Ownable2Step, Pausable, ReentrancyGuard {
    /* ============ Constants ============ */

    uint256 internal constant PRECISE_UNIT = 1e18;
    uint64 public constant MAX_DISPUTE_WINDOW = 90 days;
    uint64 public constant MAX_LOOKBACK = 30 days;
    uint64 public constant MAX_SCAN_AGE = 1 hours;

    /* ============ Immutables ============ */

    IOrchestratorV4 public immutable orchestrator;
    IStakeVaultV2 public immutable stakeVault;
    INullifierRegistryV2 public immutable nullifierRegistry;

    /* ============ State Variables ============ */

    INonPaymentVerifier public nonPaymentVerifier;

    /// @notice Dispute window per payment method; zero disables arbitrated release on that method.
    mapping(bytes32 => uint64) public disputeWindow;

    /// @notice Stake owners governance allows to back releases.
    mapping(address => bool) public isBondOwner;

    /// @notice Bond owner that authorized each operator.
    mapping(address => address) public bondOwnerOf;

    /// @notice Most stake an operator's open releases may hold locked, set by its bond owner.
    mapping(address => uint256) public operatorCap;

    /// @notice Stake currently locked by each operator's open releases.
    mapping(address => uint256) public operatorLocked;

    mapping(bytes32 => Release) internal releases;

    /* ============ Constructor ============ */

    constructor(
        address _owner,
        IOrchestratorV4 _orchestrator,
        IStakeVaultV2 _stakeVault,
        INullifierRegistryV2 _nullifierRegistry,
        INonPaymentVerifier _nonPaymentVerifier
    ) {
        if (
            _owner == address(0) || address(_orchestrator) == address(0) || address(_stakeVault) == address(0)
                || address(_nullifierRegistry) == address(0) || address(_nonPaymentVerifier) == address(0)
        ) revert ZeroAddress();
        orchestrator = _orchestrator;
        stakeVault = _stakeVault;
        nullifierRegistry = _nullifierRegistry;
        nonPaymentVerifier = _nonPaymentVerifier;
        _transferOwnership(_owner);
    }

    /* ============ Operator Functions ============ */

    /// @inheritdoc IBondedArbitrator
    function release(bytes32 _intentHash, uint256 _releaseAmount, PaymentClaim calldata _claim)
        external
        override
        whenNotPaused
        nonReentrant
    {
        address bondOwner = bondOwnerOf[msg.sender];
        if (bondOwner == address(0) || !isBondOwner[bondOwner]) revert UnauthorizedOperator(msg.sender);

        IOrchestratorV4.Intent memory intent = orchestrator.getIntent(_intentHash);
        if (intent.arbitrator != address(this)) revert NotArbitrator(_intentHash);
        uint64 window = disputeWindow[intent.paymentMethod];
        if (window == 0) revert ArbitrationDisabled(intent.paymentMethod);
        _validateClaim(intent, _releaseAmount, _claim);

        IEscrow.Deposit memory deposit = IEscrow(intent.escrow).getDeposit(intent.depositId);
        if (address(deposit.token) != address(stakeVault.stakeToken())) revert UnsupportedToken(address(deposit.token));

        uint256 locked = operatorLocked[msg.sender] + _releaseAmount;
        if (locked > operatorCap[msg.sender]) revert OperatorCapExceeded(msg.sender, locked, operatorCap[msg.sender]);
        operatorLocked[msg.sender] = locked;

        Release memory opened = Release({
            operator: msg.sender,
            bondOwner: bondOwner,
            depositor: deposit.depositor,
            releasedAt: uint64(block.timestamp),
            paymentMethod: intent.paymentMethod,
            payeeId: intent.payeeId,
            fiatCurrency: intent.fiatCurrency,
            claim: _claim
        });
        releases[_intentHash] = opened;

        // A named payment backs one intent only, across verified fulfilments and arbitrated releases.
        if (_claim.txIdHash != bytes32(0)) {
            nullifierRegistry.addNullifier(keccak256(abi.encodePacked(intent.paymentMethod, _claim.txIdHash)), _intentHash);
        }
        // The vault rejects a zero amount and the escrow rejects more than the intent holds.
        uint64 maturesAt = uint64(block.timestamp) + window;
        stakeVault.lockStake(bondOwner, _lockId(_intentHash), _releaseAmount, maturesAt);
        orchestrator.releaseFundsToPayer(_intentHash, _releaseAmount);

        emit ArbitratedRelease(_intentHash, msg.sender, bondOwner, _releaseAmount, maturesAt, opened);
    }

    /* ============ Depositor and Permissionless Functions ============ */

    /// @inheritdoc IBondedArbitrator
    /// @dev Anyone may submit: the scan is bound to the deposit's payee and the award always goes to the depositor.
    function disputeNonPayment(INonPaymentVerifier.NonPaymentAttestation calldata _attestation)
        external
        override
        nonReentrant
    {
        bytes32 intentHash = _attestation.intentHash;
        Release memory open = _openRelease(intentHash);

        (, uint256 amount, uint64 maturesAt) = stakeVault.locks(_lockId(intentHash));
        if (block.timestamp >= maturesAt) revert DisputeWindowClosed(maturesAt);

        INonPaymentVerifier.NonPaymentDetails memory scan = nonPaymentVerifier.verifyNonPayment(_attestation);
        if (
            scan.paymentMethod != open.paymentMethod || scan.payeeId != open.payeeId
                || scan.fiatCurrency != open.fiatCurrency || scan.windowStart > open.claim.paidAfter
                || scan.windowEnd < open.releasedAt || scan.claimedAmount != open.claim.amount
                || scan.payerHash != open.claim.payerHash || scan.txIdHash != open.claim.txIdHash
        ) revert ScanMismatch(intentHash);
        // The scan must reach the present, so a payment that arrived after release still defeats the dispute.
        if (uint256(scan.windowEnd) + MAX_SCAN_AGE < block.timestamp) revert StaleEvidence(scan.windowEnd);
        // A skipped payment must already back another intent, such as the same buyer's later verified order.
        for (uint256 i = 0; i < scan.excludedPaymentIds.length; i++) {
            bytes32 boundTo = nullifierRegistry.intentHashByNullifier(
                keccak256(abi.encodePacked(open.paymentMethod, scan.excludedPaymentIds[i]))
            );
            if (boundTo == bytes32(0) || boundTo == intentHash) revert UnboundExclusion(scan.excludedPaymentIds[i]);
        }
        // The unpaid share of the release; the vault returns the rest of the lock to the bond owner's free stake.
        uint256 owed = scan.receivedAmount >= scan.claimedAmount
            ? 0
            : amount * (scan.claimedAmount - scan.receivedAmount) / scan.claimedAmount;
        if (owed == 0) revert PaymentCovered(scan.receivedAmount, scan.claimedAmount);
        _close(intentHash, open.operator, amount);
        IStakeVaultV2.Claim[] memory claims = new IStakeVaultV2.Claim[](1);
        claims[0] = IStakeVaultV2.Claim({beneficiary: open.depositor, amount: owed});
        stakeVault.resolveLock(_lockId(intentHash), claims);

        emit ReleaseOverturned(intentHash, open.bondOwner, open.depositor, owed, scan.historyHash);
    }

    /// @inheritdoc IBondedArbitrator
    function acknowledge(bytes32 _intentHash) external override nonReentrant {
        Release memory open = _openRelease(_intentHash);
        if (msg.sender != open.depositor) revert UnauthorizedDepositor(msg.sender);
        _unlock(_intentHash, open, true);
    }

    /// @inheritdoc IBondedArbitrator
    function settle(bytes32[] calldata _intentHashes) external override nonReentrant {
        for (uint256 i = 0; i < _intentHashes.length; i++) {
            Release memory open = _openRelease(_intentHashes[i]);
            (,, uint64 maturesAt) = stakeVault.locks(_lockId(_intentHashes[i]));
            if (block.timestamp < maturesAt) revert NotMatured(maturesAt);
            _unlock(_intentHashes[i], open, false);
        }
    }

    /* ============ Bond Owner Functions ============ */

    /// @inheritdoc IBondedArbitrator
    /// @dev Revoking stops new releases only. Open releases keep their lock until dispute or maturity.
    function setOperator(address _operator, uint256 _cap) external override {
        if (!isBondOwner[msg.sender]) revert UnauthorizedBondOwner(msg.sender);
        if (_operator == address(0)) revert ZeroAddress();
        address current = bondOwnerOf[_operator];
        if (current != address(0) && current != msg.sender) revert OperatorTaken(_operator, current);

        if (_cap == 0) {
            delete bondOwnerOf[_operator];
        } else {
            bondOwnerOf[_operator] = msg.sender;
        }
        operatorCap[_operator] = _cap;
        emit OperatorSet(msg.sender, _operator, _cap);
    }

    /* ============ Governance Functions ============ */

    /**
     * @notice GOVERNANCE ONLY: Approves or removes a stake owner that may back releases.
     * @param _bondOwner Stake owner in StakeVaultV2.
     * @param _approved Whether its operators may release.
     */
    function setBondOwner(address _bondOwner, bool _approved) external onlyOwner {
        if (_bondOwner == address(0)) revert ZeroAddress();
        isBondOwner[_bondOwner] = _approved;
        emit BondOwnerSet(_bondOwner, _approved);
    }

    /**
     * @notice GOVERNANCE ONLY: Sets a payment method's dispute window; zero disables arbitrated release on it.
     * @param _paymentMethod Payment method hash.
     * @param _window Seconds a release's bond stays locked.
     */
    function setDisputeWindow(bytes32 _paymentMethod, uint64 _window) external onlyOwner {
        if (_window > MAX_DISPUTE_WINDOW) revert InvalidDisputeWindow(_window);
        disputeWindow[_paymentMethod] = _window;
        emit DisputeWindowSet(_paymentMethod, _window);
    }

    /**
     * @notice GOVERNANCE ONLY: Replaces the scan verifier for future disputes.
     * @param _verifier New NonPaymentVerifier.
     */
    function setNonPaymentVerifier(INonPaymentVerifier _verifier) external onlyOwner {
        if (address(_verifier) == address(0)) revert ZeroAddress();
        emit NonPaymentVerifierSet(address(nonPaymentVerifier), address(_verifier));
        nonPaymentVerifier = _verifier;
    }

    /// @notice GOVERNANCE ONLY: Stops new releases. Disputes, acknowledgements and settlement stay open.
    function pause() external onlyOwner {
        _pause();
    }

    /// @notice GOVERNANCE ONLY: Resumes releases.
    function unpause() external onlyOwner {
        _unpause();
    }

    /// @notice Ownership renunciation is disabled so governance keeps the pause and rail switches.
    function renounceOwnership() public view override onlyOwner {
        revert OwnershipRenunciationDisabled();
    }

    /* ============ View Functions ============ */

    /// @inheritdoc IBondedArbitrator
    function getRelease(bytes32 _intentHash) external view override returns (Release memory) {
        return releases[_intentHash];
    }

    /// @inheritdoc IBondedArbitrator
    function lockId(bytes32 _intentHash) external view override returns (bytes32) {
        return _lockId(_intentHash);
    }

    /* ============ Internal Functions ============ */

    /// @dev The claim must name the payment and cover what is released at the intent's rate.
    function _validateClaim(IOrchestratorV4.Intent memory _intent, uint256 _releaseAmount, PaymentClaim calldata _claim)
        internal
        view
    {
        if (uint256(_claim.paidAfter) + MAX_LOOKBACK < _intent.timestamp || _claim.paidAfter > block.timestamp) {
            revert InvalidClaimWindow(_claim.paidAfter, _intent.timestamp);
        }
        if (_claim.payerHash == bytes32(0) && _claim.txIdHash == bytes32(0)) revert UnidentifiedPayment();
        uint256 releaseFiatValue = _releaseAmount * _intent.conversionRate / PRECISE_UNIT;
        if (_claim.amount == 0 || _claim.amount < releaseFiatValue) revert ClaimBelowRelease(_claim.amount, releaseFiatValue);
    }

    function _openRelease(bytes32 _intentHash) internal view returns (Release memory open) {
        open = releases[_intentHash];
        if (open.operator == address(0)) revert ReleaseNotFound(_intentHash);
    }

    function _unlock(bytes32 _intentHash, Release memory _open, bool _acknowledged) internal {
        (, uint256 amount,) = stakeVault.locks(_lockId(_intentHash));
        _close(_intentHash, _open.operator, amount);
        stakeVault.unlockStake(_lockId(_intentHash));
        emit ReleaseSettled(_intentHash, _open.bondOwner, _acknowledged);
    }

    function _close(bytes32 _intentHash, address _operator, uint256 _amount) internal {
        delete releases[_intentHash];
        operatorLocked[_operator] -= _amount;
    }

    /// @dev Domain-separated from DisputeProtectionPolicyV2, which locks under the bare intent hash.
    function _lockId(bytes32 _intentHash) internal view returns (bytes32) {
        return keccak256(abi.encode(address(this), _intentHash));
    }
}
","keccak256":"0x8e2301327816ae3429afa7aee8c62215439f0b6f150961c7cef851c372b5ca47","license":"MIT"},"contracts/interfaces/IBondedArbitrator.sol":{"content":"// SPDX-License-Identifier: MIT

pragma solidity ^0.8.18;

import {INonPaymentVerifier} from "./INonPaymentVerifier.sol";

/**
 * @title IBondedArbitrator
 * @notice OrchestratorV4 arbitrator that releases an intent only against locked stake and lets the depositor recover
 * the unpaid share from that stake with an attestor-signed scan of the seller account.
 */
interface IBondedArbitrator {
    /// @notice The payment the operator relied on, committed at release.
    struct PaymentClaim {
        uint64 paidAfter;      // The payment was sent at or after this time; no earlier than MAX_LOOKBACK before signal
        uint256 amount;        // Fiat amount the evidence shows, in the deposit token's decimals
        bytes32 payerHash;     // keccak256 of the normalized payer display name; zero when unknown
        bytes32 txIdHash;      // Platform payment id, hashed as payment attestations hash it; zero when unknown
        bytes32 evidenceHash;  // Hash of the off-chain evidence, for audit; zero when none
    }

    /// @notice An open release: who backs it, who is owed on a dispute, and what a scan must match.
    /// @dev The locked amount and maturity live in the StakeVaultV2 lock.
    struct Release {
        address operator;
        address bondOwner;
        address depositor;     // Captured before release; paid on a proven dispute
        uint64 releasedAt;
        bytes32 paymentMethod;
        bytes32 payeeId;
        bytes32 fiatCurrency;
        PaymentClaim claim;
    }

    event ArbitratedRelease(
        bytes32 indexed intentHash,
        address indexed operator,
        address indexed bondOwner,
        uint256 amount,
        uint64 maturesAt,
        Release release
    );
    event ReleaseOverturned(
        bytes32 indexed intentHash,
        address indexed bondOwner,
        address indexed depositor,
        uint256 amount,
        bytes32 historyHash
    );
    event ReleaseSettled(bytes32 indexed intentHash, address indexed bondOwner, bool acknowledgedByDepositor);
    event OperatorSet(address indexed bondOwner, address indexed operator, uint256 cap);
    event BondOwnerSet(address indexed bondOwner, bool approved);
    event DisputeWindowSet(bytes32 indexed paymentMethod, uint64 window);
    event NonPaymentVerifierSet(address indexed previousVerifier, address indexed newVerifier);

    error ZeroAddress();
    error UnauthorizedOperator(address caller);
    error UnauthorizedBondOwner(address caller);
    error OperatorTaken(address operator, address bondOwner);
    error NotArbitrator(bytes32 intentHash);
    error ArbitrationDisabled(bytes32 paymentMethod);
    error UnsupportedToken(address token);
    error InvalidClaimWindow(uint64 paidAfter, uint256 intentTimestamp);
    error UnidentifiedPayment();
    error ClaimBelowRelease(uint256 amount, uint256 releaseFiatValue);
    error OperatorCapExceeded(address operator, uint256 locked, uint256 cap);
    error ReleaseNotFound(bytes32 intentHash);
    error DisputeWindowClosed(uint64 maturesAt);
    error ScanMismatch(bytes32 intentHash);
    error StaleEvidence(uint64 windowEnd);
    error UnboundExclusion(bytes32 paymentId);
    error PaymentCovered(uint256 receivedAmount, uint256 claimedAmount);
    error NotMatured(uint64 maturesAt);
    error UnauthorizedDepositor(address caller);
    error InvalidDisputeWindow(uint64 window);
    error OwnershipRenunciationDisabled();

    /**
     * @notice OPERATOR ONLY: Pays the intent recipient now and locks the same amount of the bond owner's stake until
     * the payment method's dispute window ends.
     * @param _intentHash Intent naming this contract as arbitrator.
     * @param _releaseAmount Deposit tokens to release; any rest returns to the deposit.
     * @param _claim Payment the operator relied on.
     */
    function release(bytes32 _intentHash, uint256 _releaseAmount, PaymentClaim calldata _claim) external;

    /**
     * @notice Pays the depositor the unpaid share of the bond shown by a fresh attestor scan of the seller account.
     * @param _attestation Signed scan for the released intent.
     */
    function disputeNonPayment(INonPaymentVerifier.NonPaymentAttestation calldata _attestation) external;

    /**
     * @notice DEPOSITOR ONLY: Confirms the payment arrived and unlocks the bond before maturity.
     * @param _intentHash Released intent.
     */
    function acknowledge(bytes32 _intentHash) external;

    /**
     * @notice Unlocks the bond of every listed release whose dispute window has ended.
     * @param _intentHashes Released intents.
     */
    function settle(bytes32[] calldata _intentHashes) external;

    /**
     * @notice BOND OWNER ONLY: Authorizes an operator to lock the caller's stake up to `_cap`; zero revokes it.
     * @param _operator Operator address.
     * @param _cap Most stake the operator's open releases may hold locked.
     */
    function setOperator(address _operator, uint256 _cap) external;

    /// @notice Returns an open release; all zero after dispute or settlement.
    function getRelease(bytes32 _intentHash) external view returns (Release memory);

    /// @notice Returns the StakeVaultV2 lock id that holds a release's bond.
    function lockId(bytes32 _intentHash) external view returns (bytes32);
}
","keccak256":"0x6ba26b88d7ebbc6396dcc61572aebb57ff3a4cb3369784ee08f3cc592dbdba16","license":"MIT"},"contracts/interfaces/IEscrow.sol":{"content":"// SPDX-License-Identifier: MIT

pragma solidity ^0.8.18;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { IPostIntentHook } from "./IPostIntentHook.sol";

interface IEscrow {

    /* ============ Structs ============ */

    struct Intent {
        bytes32 intentHash;                        // Unique identifier for the intent
        uint256 amount;                            // Amount locked
        uint256 timestamp;                         // When this intent was created
        uint256 expiryTime;                        // When this intent expires
    }

    struct Range {
        uint256 min;                                // Minimum value
        uint256 max;                                // Maximum value
    }

    struct Deposit {
        address depositor;                          // Address of depositor
        address delegate;                           // Address that can manage this deposit (address(0) if no delegate)
        IERC20 token;                               // Address of deposit token
        Range intentAmountRange;                    // Range of take amount per intent
        // Deposit state
        bool acceptingIntents;                      // State: True if the deposit is accepting intents, False otherwise
        uint256 remainingDeposits;                  // State: Amount of liquidity immediately available to lock
        uint256 outstandingIntentAmount;            // State: Amount of outstanding intents (may include expired intents)
        // Intent guardian
        address intentGuardian;                     // Address that can extend intent expiry times (address(0) if no guardian)
        // Retention behavior
        bool retainOnEmpty;                         // If true, do not auto-close/sweep when empty; keep config for reuse
    }

    struct Currency {
        bytes32 code;                               // Currency code (keccak256 hash of the currency code)
        uint256 minConversionRate;                  // Minimum rate of deposit token to fiat currency (in preciseUnits)
    }

    struct DepositPaymentMethodData {
        address intentGatingService;                // Public key of gating service that will be used to verify intents
        bytes32 payeeDetails;                       // Payee details, has to be hash of payee details
        bytes data;                                 // Verification Data: Additional data used for payment verification; Can hold attester address
                                                    // in case of TLS proofs, domain key hash in case of zkEmail proofs, currency code etc.
    }

    struct CreateDepositParams {
        IERC20 token;                                // The token to be deposited
        uint256 amount;                              // The amount of token to deposit
        Range intentAmountRange;                     // The max and min take amount for each intent
        bytes32[] paymentMethods;                    // The payment methods that deposit supports
        DepositPaymentMethodData[] paymentMethodData;// The payment verification data for each payment method that deposit supports
        Currency[][] currencies;                     // The currencies for each payment method that deposit supports
        address delegate;                            // Optional delegate address that can manage this deposit (address(0) for no delegate)
        address intentGuardian;                      // Optional intent guardian address that can extend intent expiry times (address(0) for no guardian)
        bool retainOnEmpty;                          // Opt-in: keep deposit and config when empty
    }

    /* ============ Events ============ */

    event DepositReceived(uint256 indexed depositId, address indexed depositor, IERC20 indexed token, uint256 amount, Range intentAmountRange, address delegate, address intentGuardian);

    event DepositPaymentMethodAdded(uint256 indexed depositId, bytes32 indexed paymentMethod, bytes32 indexed payeeDetails, address intentGatingService);
    event DepositPaymentMethodActiveUpdated(uint256 indexed depositId, bytes32 indexed paymentMethod, bool active);

    event DepositCurrencyAdded(uint256 indexed depositId, bytes32 indexed paymentMethod, bytes32 indexed currency, uint256 minConversionRate);
    event DepositMinConversionRateUpdated(uint256 indexed depositId, bytes32 indexed paymentMethod, bytes32 indexed currency, uint256 newMinConversionRate);

    event DepositFundsAdded(uint256 indexed depositId, address indexed depositor, uint256 amount);
    event DepositWithdrawn(uint256 indexed depositId, address indexed depositor, uint256 amount);
    event DepositClosed(uint256 depositId, address depositor);
    event DepositAcceptingIntentsUpdated(uint256 indexed depositId, bool acceptingIntents);

    event DepositIntentAmountRangeUpdated(uint256 indexed depositId, Range intentAmountRange);
    event DepositRetainOnEmptyUpdated(uint256 indexed depositId, bool retainOnEmpty);

    event DepositDelegateSet(uint256 indexed depositId, address indexed depositor, address indexed delegate);
    event DepositDelegateRemoved(uint256 indexed depositId, address indexed depositor);

    event MinDepositAmountSet(uint256 minDepositAmount);

    event OrchestratorUpdated(address indexed orchestrator);
    event PaymentVerifierRegistryUpdated(address indexed paymentVerifierRegistry);

    event FundsLocked(uint256 indexed depositId, bytes32 indexed intentHash, uint256 amount, uint256 expiryTime);
    event FundsUnlocked(uint256 indexed depositId, bytes32 indexed intentHash, uint256 amount);
    event FundsUnlockedAndTransferred(
        uint256 indexed depositId, 
        bytes32 indexed intentHash, 
        uint256 unlockedAmount, 
        uint256 transferredAmount, 
        address to
    );
    event IntentExpiryExtended(uint256 indexed depositId, bytes32 indexed intentHash, uint256 newExpiryTime);

    event DustRecipientUpdated(address indexed dustRecipient);
    event DustCollected(uint256 indexed depositId, uint256 dustAmount, address indexed dustRecipient);
    event DustThresholdUpdated(uint256 dustThreshold);
    event MaxIntentsPerDepositUpdated(uint256 maxIntentsPerDeposit);
    event IntentExpirationPeriodUpdated(uint256 intentExpirationPeriod);

    /* ============ Standardized Custom Errors ============ */

    // Zero value errors
    error ZeroAddress();
    error ZeroValue();
    error ZeroMinValue();
    error ZeroConversionRate();

    // Authorization errors
    error UnauthorizedCaller(address caller, address authorized);
    error UnauthorizedCallerOrDelegate(address caller, address owner, address delegate);
    error CannotDelegateToSelf(address depositor);

    // Range and amount errors
    error InvalidRange(uint256 min, uint256 max);
    error AmountBelowMin(uint256 amount, uint256 min);
    error AmountAboveMax(uint256 amount, uint256 max);
    error AmountExceedsAvailable(uint256 requested, uint256 available);

    // Not found errors
    error DepositNotFound(uint256 depositId);
    error IntentNotFound(bytes32 intentHash);
    error PaymentMethodNotActive(uint256 depositId, bytes32 paymentMethod);
    error PaymentMethodNotListed(uint256 depositId, bytes32 paymentMethod);
    error CurrencyNotFound(bytes32 paymentMethod, bytes32 currency);
    error DelegateNotFound(uint256 depositId);

    // Already exists errors
    error PaymentMethodAlreadyExists(uint256 depositId, bytes32 paymentMethod);
    error CurrencyAlreadyExists(bytes32 paymentMethod, bytes32 currency);
    error IntentAlreadyExists(uint256 depositId, bytes32 intentHash);

    // State errors
    error DepositNotAcceptingIntents(uint256 depositId);
    error DepositAlreadyInState(uint256 depositId, bool currentState);
    error InsufficientDepositLiquidity(uint256 depositId, uint256 available, uint256 required);
    error MaxIntentsExceeded(uint256 depositId, uint256 current, uint256 max);

    // Validation errors
    error EmptyPayeeDetails();
    error ArrayLengthMismatch(uint256 length1, uint256 length2);

    // Payment method errors
    error PaymentMethodNotWhitelisted(bytes32 paymentMethod);
    error CurrencyNotSupported(bytes32 paymentMethod, bytes32 currency);


    /* ============ External Functions for Orchestrator ============ */

    function lockFunds(uint256 _depositId, bytes32 _intentHash, uint256 _amount) external;
    function unlockFunds(uint256 _depositId, bytes32 _intentHash) external;
    function unlockAndTransferFunds(uint256 _depositId, bytes32 _intentHash, uint256 _transferAmount, address _to) external;
    function extendIntentExpiry(uint256 _depositId, bytes32 _intentHash, uint256 _additionalTime) external;

    /* ============ View Functions ============ */

    function getDeposit(uint256 _depositId) external view returns (Deposit memory);
    function getDepositIntent(uint256 _depositId, bytes32 _intentHash) external view returns (Intent memory);
    function getDepositPaymentMethods(uint256 _depositId) external view returns (bytes32[] memory);
    function getDepositCurrencies(uint256 _depositId, bytes32 _paymentMethod) external view returns (bytes32[] memory);
    function getDepositCurrencyMinRate(uint256 _depositId, bytes32 _paymentMethod, bytes32 _currencyCode) external view returns (uint256);
    function getDepositPaymentMethodData(uint256 _depositId, bytes32 _paymentMethod) external view returns (DepositPaymentMethodData memory);
    function getDepositPaymentMethodActive(uint256 _depositId, bytes32 _paymentMethod) external view returns (bool);
    function getDepositGatingService(uint256 _depositId, bytes32 _paymentMethod) external view returns (address);
    function getDepositIntentHashes(uint256 _depositId) external view returns (bytes32[] memory);
    function getExpiredIntents(uint256 _depositId) external view returns (bytes32[] memory expiredIntents, uint256 reclaimableAmount);
}
